"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "payments",
        "name": "payments-worker",
        "uid": "uid-deployment-payments-worker"
    },
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Increase liveness probe timeout to allow new version sufficient time to start before probe fails",
    "rationale": "The new version (2.11.1) shows startup delays (46s before kill) but has liveness probe timeout set to 2s. Increasing timeout to 5s would allow the app to respond before probe fails, while keeping other probe parameters unchanged.",
